contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    receive() external payable {}
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        c.fallback{value: amount}();
        uint balBefore = c.balances(address(this));
        uint contractBalBefore = address(c).balance;
        bool reverted;
        try c.withdraw() { reverted = false; } catch { reverted = true; }
        uint balAfter = c.balances(address(this));
        uint contractBalAfter = address(c).balance;
        assert(!reverted && balAfter == 0 && contractBalAfter + balBefore >= contractBalBefore && contractBalAfter == contractBalBefore - balBefore);
    }
}

