contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address user, uint256 depositAmount, uint256 withdrawAmount) public payable {
        require(user != address(0), "invalid user");
        require(depositAmount > 0, "deposit must be positive");
        require(withdrawAmount == depositAmount, "withdraw must equal deposit");
        require(address(this).balance >= depositAmount, "not enough balance");

        uint256 beforeContractBalance = address(c).balance;
        c.balances{value: depositAmount}(user);
        uint256 recordedBalance = c.balances(user);

        bool reverted;
        try c.withdraw() {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            assert(c.balances(user) == 0);
            assert(address(c).balance == beforeContractBalance + depositAmount - withdrawAmount);
        } else {
            assert(c.balances(user) == recordedBalance);
            assert(address(c).balance == beforeContractBalance + depositAmount);
        }

        assert(!reverted);
    }

    receive() external payable {}
}

