contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, uint withdrawAmount) public payable {
        // Send ether to c through the fallback, crediting this test contract
        require(address(this).balance >= amount);
        (bool depositOk, ) = address(c).call{value: amount}("");
        require(depositOk);

        // Record balances before withdraw
        uint cBefore = address(c).balance;
        uint credited = c.balances(address(this));

        // If the credited balance is less than the requested withdrawAmount, we adjust
        // to guarantee that withdraw cannot fail due to insufficient balance incorrectly.
        uint requested = withdrawAmount > credited ? credited : withdrawAmount;

        // Attempt withdraw; record success
        bool withdrawOk;
        try c.withdraw() {
            withdrawOk = true;
        } catch {
            withdrawOk = false;
        }

        // After a successful withdraw, the credited balance must have decreased by at
        // least the requested amount (and be zero), and c's balance must decrease by
        // the same amount. A successful withdraw cannot leave the contract balance
        // un-decremented, nor fail to clear the deposit.
        if (withdrawOk) {
            uint cAfter = address(c).balance;
            // The withdraw sends `credited` (the full balance) to this contract.
            // So c's balance must have decreased by `credited` and the credited
            // balance must be zero.
            assert(cAfter == cBefore - credited && c.balances(address(this)) == 0);
        }
    }

    receive() external payable {}
}

