            assert(c.balances(address(this)) == 0);
            assert(address(c).balance == contractBalBefore + depositAmount - balAfterDeposit);
        } else {
            // A revert must leave the caller's recorded balance unchanged.
            assert(c.balances(address(this)) == balAfterDeposit);
        }
    }

    receive() external payable {}
}

