    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);

        c.balances(address(this));

        c.fallback{value: amount}();

        c.balances(address(this));

        uint256 balanceBefore = c.balances(address(this));
        uint256 contractBalanceBefore = address(c).balance;
        uint256 testBalanceBefore = address(this).balance;
        require(balanceBefore > 0);

        bool reverted;
        try c.withdraw() {
            reverted = false;
        } catch {
            reverted = true;
        }

