            reverted ||
            (
                c.balances(address(this)) == 0 &&
                address(c).balance == contractBalanceBefore - balanceBefore &&
                address(this).balance == testBalanceBefore + balanceBefore
            )
        );
    }

    receive() external payable {}
}

